//! Bounded knowledge-representation research copilots for Worldgen P04 F09-F12.

use std::collections::BTreeSet;
use super::knowledge_representation_support::{self, KnowledgeRepresentationRequest};
use bioprism_foundation::{PRECLINICAL_BOUNDARY, RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize, Serialize};
use serde_json::json;
use thiserror::Error;

pub const CONTENT_TYPE: &str = "application/vnd.aurora.worldgen.knowledge-copilot-receipt+json";

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct KnowledgeCopilotRequest { pub knowledge_request: KnowledgeRepresentationRequest, pub action_order: Vec<String>, pub action_budget: u64, pub dry_run: bool, pub signed_approval: bool, pub federation_approved: bool, pub boundary: String }
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct KnowledgeCopilotReceipt { pub schema_version: String, pub contract_version: String, pub feature_id: String, pub request_id: String, pub disposition: String, pub action_order: Vec<String>, pub admitted_action_order: Vec<String>, pub denied_action_order: Vec<String>, pub knowledge_disposition: String, pub graph_digest: ContentHash, pub copilot_digest: ContentHash, pub replay_identity: ContentHash, pub omissions: Vec<String>, pub uncertainty: Vec<String>, pub negative_evidence: Vec<String>, pub effect_receipts: Vec<String>, pub artifact: serde_json::Value, pub raw_data_local: bool, pub aggregate_only: bool, pub boundary: String }
#[derive(Debug, Error, Clone, PartialEq, Eq)]
pub enum KnowledgeCopilotError { #[error("invalid knowledge copilot request: {0}")] Invalid(String), #[error("knowledge copilot representation failed: {0}")] Representation(String), #[error("knowledge copilot artifact failed: {0}")] Artifact(String), #[error("invalid knowledge copilot receipt: {0}")] Receipt(String) }
fn digest(value:&ContentHash)->bool{value.as_str().len()==64&&value.as_str().bytes().all(|byte|byte.is_ascii_hexdigit())} fn ordered(values:&[String])->bool{values.windows(2).all(|pair|pair[0]<pair[1])} fn sorted(values:Vec<String>)->Vec<String>{let mut out=values;out.sort();out.dedup();out}
impl KnowledgeCopilotReceipt { pub fn validate(&self)->Result<(),KnowledgeCopilotError>{if self.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||self.boundary!=PRECLINICAL_BOUNDARY||self.artifact.get("boundary").and_then(|value|value.as_str())!=Some(PRECLINICAL_BOUNDARY)||self.artifact.get("content_type").and_then(|value|value.as_str())!=Some(CONTENT_TYPE)||!self.raw_data_local||!self.aggregate_only||self.request_id.trim().is_empty()||self.action_order.is_empty()||self.effect_receipts.is_empty()||![&self.graph_digest,&self.copilot_digest,&self.replay_identity].into_iter().all(digest){return Err(KnowledgeCopilotError::Receipt("knowledge copilot identity, locality, actions, digests, or effects are incomplete".into()));}for values in [&self.action_order,&self.admitted_action_order,&self.denied_action_order,&self.omissions,&self.uncertainty,&self.negative_evidence,&self.effect_receipts]{if !ordered(values){return Err(KnowledgeCopilotError::Receipt("knowledge copilot ordering is not canonical".into()));}}let ids=self.action_order.iter().cloned().collect::<BTreeSet<_>>();let parts=self.admitted_action_order.iter().chain(&self.denied_action_order).cloned().collect::<Vec<_>>();if ids.len()!=self.action_order.len()||parts.len()!=ids.len()||parts.iter().cloned().collect::<BTreeSet<_>>()!=ids{return Err(KnowledgeCopilotError::Receipt("knowledge copilot actions do not partition".into()));}if self.effect_receipts.iter().any(|effect|effect!="block:unsafe-release"&&!effect.starts_with("invoke:bounded-knowledge-tool:")){return Err(KnowledgeCopilotError::Receipt("knowledge copilot effect is outside bounded-tool gate".into()));}Ok(())} }
pub fn manifest(feature_id:&str,version:&str,input_schema:&str,scale:&str,autonomy:&str)->serde_json::Value{json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"capability_id":feature_id,"version":version,"owner_crate":"worldgen","consumers":["knowledge engineer","preclinical researcher","graph compiler"],"behavior":format!("run bounded typed knowledge-graph actions for {scale}"),"value":"turns knowledge representation into an approval-bounded agent product without hiding unsupported edges","input_schema":input_schema,"output_schema":"KnowledgeCopilotReceipt1@1","effects":["invoke:bounded-knowledge-tool","block:unsafe-release"],"permissions":["invoke:declared-knowledge-tool"],"determinism":"byte_stable","autonomy_tier":autonomy,"boundary":PRECLINICAL_BOUNDARY,"contract_version":version})}
pub fn run(request:&KnowledgeCopilotRequest,feature_id:&str,version:&str,scale:&str,require_approval:bool,require_federation:bool)->Result<KnowledgeCopilotReceipt,KnowledgeCopilotError>{if request.boundary!=PRECLINICAL_BOUNDARY||request.knowledge_request.boundary!=PRECLINICAL_BOUNDARY||!request.knowledge_request.raw_data_local||!request.knowledge_request.aggregate_only||request.action_order.is_empty()||!ordered(&request.action_order)||request.action_order.iter().collect::<BTreeSet<_>>().len()!=request.action_order.len()||request.action_budget==0{return Err(KnowledgeCopilotError::Invalid("knowledge copilot boundary, actions, budget, locality, or boundary is invalid".into()));}let graph=knowledge_representation_support::represent(&request.knowledge_request,feature_id,version,scale,require_federation).map_err(|error|KnowledgeCopilotError::Representation(error.to_string()))?;let mut omissions=graph.omissions.clone();let approvals=(!require_approval||request.signed_approval)&&(!require_federation||request.federation_approved);if !approvals{omissions.push("copilot:approval-missing".into());}if request.dry_run{omissions.push("copilot:dry-run-no-effect".into());}if request.action_order.len() as u64>request.action_budget{omissions.push("copilot:action-budget-exceeded".into());}let safe=graph.disposition=="qualified"&&approvals&&request.action_order.len() as u64<=request.action_budget;let disposition=if safe{"qualified"}else if graph.disposition=="blocked"||!approvals{"blocked"}else{"partial"};let admitted=if safe{request.action_order.clone()}else{Vec::new()};let denied=if safe{Vec::new()}else{request.action_order.clone()};let effects=if disposition=="blocked"{vec!["block:unsafe-release".into()]}else{vec![format!("invoke:bounded-knowledge-tool:{}",request.knowledge_request.request_id)]};let payload=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":version,"feature_id":feature_id,"request_id":request.knowledge_request.request_id,"disposition":disposition,"action_order":request.action_order,"admitted_action_order":admitted,"denied_action_order":denied,"knowledge_disposition":graph.disposition,"graph_digest":graph.graph_digest,"replay_identity":graph.replay_identity,"omissions":sorted(omissions),"uncertainty":graph.uncertainty,"negative_evidence":graph.negative_evidence,"effect_receipts":effects,"raw_data_local":true,"aggregate_only":true,"boundary":PRECLINICAL_BOUNDARY});let copilot_digest=ContentHash::of_value(&payload).map_err(|error|KnowledgeCopilotError::Artifact(error.to_string()))?;let artifact=json!({"artifact_id":format!("knowledge-copilot:{}",request.knowledge_request.request_id),"content_type":CONTENT_TYPE,"content_hash":copilot_digest,"boundary":PRECLINICAL_BOUNDARY});let receipt=KnowledgeCopilotReceipt{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:version.into(),feature_id:feature_id.into(),request_id:request.knowledge_request.request_id.clone(),disposition:disposition.into(),action_order:request.action_order.clone(),admitted_action_order:admitted,denied_action_order:denied,knowledge_disposition:graph.disposition,graph_digest:graph.graph_digest,copilot_digest,replay_identity:graph.replay_identity,omissions:sorted(payload["omissions"].as_array().unwrap().iter().map(|value|value.as_str().unwrap().to_owned()).collect()),uncertainty:graph.uncertainty,negative_evidence:graph.negative_evidence,effect_receipts:effects,artifact,raw_data_local:true,aggregate_only:true,boundary:PRECLINICAL_BOUNDARY.into()};receipt.validate()?;Ok(receipt)}
#[cfg(test)]mod tests{use super::*;use crate::knowledge_representation_support::{KnowledgeNode,KnowledgeRelation};fn hash(seed:&str)->ContentHash{ContentHash::of_bytes(seed.as_bytes())}fn request()->KnowledgeCopilotRequest{let replay=hash("replay");let node=KnowledgeNode{node_id:"node:a".into(),semantic_type:"gene".into(),label:"A".into(),confidence_milli:900,state:bioprism_foundation::EvidenceState::Supported,evidence_digest:hash("e"),provenance_digest:hash("p"),artifact_digest:hash("a"),replay_identity:replay.clone(),negative_result:false,raw_data_local:true,boundary:PRECLINICAL_BOUNDARY.into()};let relation=KnowledgeRelation{relation_id:"rel:a".into(),subject_id:"node:a".into(),predicate:"associated-with".into(),object_id:"node:a".into(),evidence_digest:hash("re"),provenance_digest:hash("rp"),replay_identity:replay.clone(),raw_data_local:true,boundary:PRECLINICAL_BOUNDARY.into()};KnowledgeCopilotRequest{knowledge_request:KnowledgeRepresentationRequest{request_id:"copilot:req".into(),namespace:"preclinical".into(),required_node_order:vec!["node:a".into()],required_relation_order:vec!["rel:a".into()],minimum_confidence_milli:500,nodes:vec![node],relations:vec![relation],replay_identity:replay,policy_allow:true,protected_closure:true,federation_approved:true,raw_data_local:true,aggregate_only:true,boundary:PRECLINICAL_BOUNDARY.into()},action_order:vec!["read:graph".into()],action_budget:2,dry_run:false,signed_approval:true,federation_approved:true,boundary:PRECLINICAL_BOUNDARY.into()}}#[test]fn qualified_tool_is_bounded(){let r=run(&request(),"AFA-worldgen-P04-F09","worldgen-local-knowledge-copilot/1.0","local single-study",false,false).unwrap();assert_eq!(r.disposition,"qualified");}#[test]fn budget_failure_is_partial(){let mut q=request();q.action_order=vec!["a".into(),"b".into()];q.action_budget=1;let r=run(&q,"AFA-worldgen-P04-F11","worldgen-throughput-knowledge-copilot/1.0","prospective high-throughput",true,true).unwrap();assert_eq!(r.disposition,"partial");}}
